/bin/zsh -lc "python3 -c 'import json
with open(\"input.json\") as f:
    data = json.load(f)
jobs = {j: {\"id\": j, \"state\": \"PENDING\", \"attempt\": 0, \"lease_until\": None} for j in data[\"jobs\"]}
accepted, rejected, tokens = [], [], set()
def expire(t):
    for j in jobs.values():
        if j[\"state\"] == \"RUNNING\" and j[\"lease_until\"] <= t:
            j.update(state=\"PENDING\", lease_until=None)
for e in sorted(data[\"events\"], key=lambda e: (e[\"time\"], e[\"sequence\"])):
    expire(e[\"time\"])
    j = jobs[e[\"job\"]]
    ok = False
    if e[\"kind\"] == \"START\" and j[\"state\"] == \"PENDING\":
        ok = True
        j.update(state=\"RUNNING\", attempt=j[\"attempt\"] + 1, lease_until=e[\"time\"] + e[\"lease\"])
    elif e[\"kind\"] == \"RESULT\" and j[\"state\"] == \"RUNNING\" and e[\"attempt\"] == j[\"attempt\"] and e[\"token\"] not in tokens:
        ok = True
        j.update(state=\"DONE\", lease_until=None)
        tokens.add(e[\"token\"])
    elif e[\"kind\"] == \"CANCEL\" and j[\"state\"] not in (\"DONE\", \"CANCELLED\"):
        ok = True
        j.update(state=\"CANCELLED\", lease_until=None)
    (accepted if ok else rejected).append(e[\"sequence\"])
expire(data[\"horizon\"])
result = {\"jobs\": [jobs[j] for j in sorted(jobs)], \"accepted_sequences\": accepted, \"rejected_sequences\": rejected, \"accepted_tokens\": sorted(tokens)}
print(json.dumps(result, separators=(\",\", \":\")))'"

